mapper.select:
select field_id, report_type, std_code, std_name, source_expr, convert_rule, data_type, required, order_num from sys_status_report_field
and report_type = #{reportType}
order by report_type asc, order_num asc

select cl.course_code as kch, cl.course_name as kcm, cl.course_name_en as kcmcyw, cast(cl.credit as char) as xf, ifnull(cl.total_hours, ifnull(cl.theory_hours, 0) + ifnull(cl.practice_hours, 0)) as zxs, ifnull(cl.theory_hours, 0) as llxs, ifnull(cl.practice_hours, 0) as sjxs, case when cl.course_type like '%必修%' then '1' when cl.course_type like '%公选%' then '3' when cl.course_type like '%选修%' then '2' else '9' end as kcxzdm, cl.course_category as kclb, case when cl.assessment_method like '%考试%' then '1' when cl.assessment_method like '%考查%' then '2' else '9' end as kskfms, ifnull(d.dept_name, '教务处') as ssyx from tpm_course_library cl left join tpm_training_plan p on cl.plan_id = p.plan_id left join brm_department d on p.dept_id = d.dept_id
and cl.status = '0' and ifnull(cl.del_flag, '0') = '0' and p.dept_id = #{deptId}
order by cl.course_code asc

select t.teacher_code as jsgh, t.teacher_name as xm, case t.gender when '0' then '1' when '1' then '2' else '9' end as xbdm, ifnull(d.dept_name, '') as ssyx, t.title as zcdm, t.education as xldm, t.phone as lxdh, t.email as dzyx, case when ifnull(t.status, '0') = '0' then 'Y' else 'N' end as sfjs from brm_teacher t left join brm_department d on t.dept_id = d.dept_id
and t.dept_id = #{deptId}
order by t.teacher_code asc



     and report_type = #{reportType}
     and report_year = #{reportYear}
     and batch_status = #{batchStatus}
     and report_name like concat('%', #{reportName}, '%')

order by batch_id desc

mapper.update:
update sys_status_report_batch
report_type = #{reportType}, report_year = #{reportYear}, report_name = #{reportName}, scope_dept_id = #{scopeDeptId}, scope_dept_name = #{scopeDeptName}, row_count = #{rowCount}, batch_status = #{batchStatus}, gen_time = #{genTime}, export_time = #{exportTime}, submit_time = #{submitTime}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime},
where batch_id = #{batchId}
